insert into content.content_block (place_id,section,slot,ord,body,fact_refs,status,author,field)
select 'area:grand-massif',v.section,v.slot,v.ord,v.body,v.refs::text[],'review','loader',v.field from (values
('access','note',0,'Road distances are the fastest route by the OSRM router on OpenStreetMap data, without traffic or snow. Buses: <a href="https://www.altibus.com/en/arriving-by-train/cluses">Altibus</a> and <a href="https://guide-ski.fr/?p=7797">Guide Ski for Flaine</a>. Winter equipment rules: <a href="https://www.allopneus.com/guide-pratique/auto/conseils-pneu/loi-montagne-haute-savoie">Allopneus</a> (October 2026). Parking: <a href="https://www.samoens.com/en/samoens-grand-massif-area/">the Samoëns tourist office</a> and <a href="https://www.skiinfo.fr/news/le-grand-massif-flaine-vs-les-carroz">Skiinfo</a>.','{}','access.accessNote'),
('access','heading',1,'How far each base reaches','{}','access.basesH3'),
('access','para',3,'Samoëns 1600 is the hub. From the top of the Grand Massif Express, Flaine, Les Carroz and Morillon 1100 are each {{f:F000794|w}} lift ride away, and a lift top above 2,400 m is {{f:F000799|w}}.',array['F000794','F000799'],'access.basesParas.0'),
('access','para',4,'Flaine is the base for the high skiing: the Grandes Platières is {{f:F000757|w}} lift rides from the village lifts. The other villages are further: Les Carroz needs {{f:F000753|w}} rides and Morillon 1100 {{f:F000755|w}}.',array['F000753','F000755','F000757'],'access.basesParas.1'),
('access','para',5,'The valley villages trade a first lift for their charm. Samoëns village is {{f:F000772|w}} gondola ride from Samoëns 1600 and Morillon village {{f:F000767|w}} from Morillon 1100, while Morillon village is {{f:F000769|w}} lift rides from the top of the area. Sixt has no lift into the area, so the skibus to Samoëns comes first.',array['F000767','F000769','F000772'],'access.basesParas.2'),
('access','caption',0,'Lift rides from each base','{}','access.basesCaption'),
('access','line',0,'To Flaine','{}','access.baseCols.0'),
('access','line',1,'To Les Carroz','{}','access.baseCols.1'),
('access','line',2,'To Samoëns 1600','{}','access.baseCols.2'),
('access','line',3,'To Morillon 1100','{}','access.baseCols.3'),
('access','line',4,'To Sixt','{}','access.baseCols.4'),
('access','line',5,'To a lift top above 2,400 m','{}','access.baseCols.5'),
('access','line',6,'Flaine Forum','{}','access.bases.0.base'),
('access','line',7,'Flaine Forêt, by the Gérats chair','{}','access.bases.1.base'),
('access','line',8,'Les Carroz, by the Kédeuze gondola','{}','access.bases.2.base'),
('access','line',9,'Morillon village','{}','access.bases.3.base'),
('access','line',10,'Morillon 1100','{}','access.bases.4.base'),
('access','line',11,'Samoëns village, by the Grand Massif Express','{}','access.bases.5.base'),
('access','line',12,'Vercland','{}','access.bases.6.base'),
('access','line',13,'Samoëns 1600','{}','access.bases.7.base'),
('access','line',14,'Sixt','{}','access.bases.8.base'),
('access','note',1,'Fewest lift rides from the base''s own lifts before reaching the first lift of each area, on the OpenStreetMap lift and piste network. A zero to Sixt from Samoëns is the free skibus; from Flaine, Sixt is reached down the Cascades. Times are not included.','{}','access.basesNote'),
('snowboard','kicker',0,'Snowboarders','{}','chapters.0.kicker'),
('snowboard','heading',0,'Riding the Grand Massif on a board','{}','chapters.0.h2'),
('snowboard','para',0,'Flaine is the freestyle centre. skiresort.com lists the Jam Park at the Aujon drag, with kickers, rails, boxes, a hip and waves, and the Flaine tourist office adds Ze Quartz Park on the Émeraude run, the Funny Slope under the Grands Vans chair and Urban''z, a zone of jumps and modules near the Ballacha drag. A boardercross with banked turns completes the set. Morillon keeps a small Kids Park at the Esserts chair for first rides.','{}','chapters.0.paras.0'),
('snowboard','para',1,'After fresh snow the bowl above Flaine is the place to be. The Combe de Gers is marked but never groomed, about eight hundred metres of north facing slope with the Onyx and Jais lines, and the tourist office points to Agate, Diamant Noir and the Combe de Véret as a gentler way into ungroomed snow. Guide Ski names Gers, Lindars, Véret and Diamant Noir as the off piste sectors, each open only when snow, wind and the avalanche risk allow.','{}','chapters.0.paras.1'),
('snowboard','para',2,'Drags are the catch. In the map data {{f:F000731}} of Flaine''s main lifts and {{f:F000736}} at Les Carroz are drags, and the Gers drag that serves the combe is a long pull. Morillon is easier going, with drags only {{f:F000741}} of its main lifts, and the long blues through the trees above Morillon and Les Carroz suit a board on a flat light day.',array['F000731','F000736','F000741'],'chapters.0.paras.2'),
('snowboard','para',3,'The Flaine tourist office announces avalanche control the evening before on its social pages, and asks riders beyond the markers to carry a shovel, probe and transceiver, never to go alone and to go with a guide or instructor.','{}','chapters.0.paras.3'),
('snowboard','heading',1,'Parks and places to ride','{}','chapters.0.listTitle'),
('snowboard','note',0,'Parks and off piste: <a href="https://www.skiresort.com/en/ski-resort/le-grand-massif-flaine-les-carroz-morillon-samoens-sixt/test-result/snow-park/">skiresort.com</a>, <a href="https://www.flaine.com/en/freeride-fun-zones/page/2/">the Flaine tourist office</a> and <a href="https://guide-ski.fr/?p=7797">Guide Ski for Flaine</a>. Drag shares from OpenStreetMap. Terrain beyond the markers is not controlled; the avalanche bulletin and a local guide come first.','{}','chapters.0.note'),
('families','kicker',0,'Families','{}','chapters.1.kicker'),
('families','heading',0,'Holidays with children','{}','chapters.1.h2'),
('families','para',0,'The learning slopes are high and wide. Samoëns 1600, at the top of the Grand Massif Express, has {{f:F000683|w}} beginner lifts, a covered carpet and the green Septi Snake, one of the largest learning areas in Haute-Savoie by the tourist office''s account, and the ski school meets at the gondola. Morillon 1100 has the sunny Plateau des Esserts and the Marvel run through the spruce, and Flaine has the Pré, Michalet and Bissac carpets by the Front de Neige.',array['F000683'],'chapters.1.paras.0'),
('families','para',1,'Three of the villages carry the Famille Plus label. Les Carroz has held it since {{f:F000677}}, with a nursery from three months, children''s ski clubs, a toboggan run, bowling and the Aquacîme spa, and a covered carpet and a free nursery slope in the village centre. Samoëns and Morillon hold it too, and Morillon''s ski school takes children from age {{f:F000689|n}} in its Piou-Piou club.',array['F000677','F000689'],'chapters.1.paras.1'),
('families','para',2,'Children under {{f:F000688|n}} ski free by the day and pay {{f:F000693}} for two to seven days, which keeps the cost down for young families. Morillon 1100 is a car free cluster of flats at the foot of the lifts, and in Flaine the Forum is closed to cars, with the beginner lifts a few steps from the flats.',array['F000688','F000693'],'chapters.1.paras.2'),
('families','para',3,'Off the slopes, the Lac Bleu at Morillon has snowshoe walks, pony rides and cross country trails. Sixt''s Salvagny slopes, two greens and four blues with snowmaking across the beginner area, are a quiet place for a first star, and the valley Nordic trail runs about {{f:F000687}} along the Giffre when snow allows.',array['F000687'],'chapters.1.paras.3'),
('families','heading',1,'For children','{}','chapters.1.listTitle'),
('families','note',0,'Sources: <a href="https://www.samoens.com/en/samoens-grand-massif-area/">the Samoëns tourist office</a>, <a href="https://lescarroz.com/en/domaine-skiable/les-carroz-ski-area-les-carroz-daraches">the Les Carroz tourist office</a>, <a href="https://www.skiinfo.fr/news/le-grand-massif-flaine-vs-les-carroz">Skiinfo</a>, <a href="https://www.ernalow.co.uk/en-gb/france/morillon">Ernalow for Morillon</a>, <a href="https://guide-ski.fr/?p=10423">Guide Ski for Sixt</a> and <a href="https://www.flaine.com/en/winter/skiing-snowsports/ski-passes/ski-passes.htm">the Flaine tourist office</a>.','{}','chapters.1.note'),
('food','kicker',0,'Food and villages','{}','chapters.2.kicker'),
('food','heading',0,'Eating in the villages and on the mountain','{}','chapters.2.h2'),
('food','para',0,'Samoëns is the village to stay in for anyone who cares about the place itself. It grew on the skill of its frahans, the stone masons first recorded here in {{f:F000674}}, whose brotherhood survives as the Société des Maçons, and it is the only ski resort classified by France''s national monuments body. The old centre gathers round the Place du Gros-Tilleul and the Grenette hall, and Marie-Louise Cognacq-Jaÿ gave the village the Jaÿsinia, an alpine garden opened in {{f:F000675}} that holds some four and a half thousand kinds of alpine flower.',array['F000674','F000675'],'chapters.2.paras.0'),
('food','para',1,'The best tables are in Samoëns too. Le Lodge holds a Michelin Bib Gourmand, Gault&Millau gave a toque to Le 8M des Monts in its 2022 guide, and Le Monde à l''Envers near the main square is the Savoyard address Alpine Answers says to book. In Les Carroz, La Croix de Savoie held a Gault&Millau toque in the same guide.','{}','chapters.2.paras.1'),
('food','para',2,'On the mountain the Les Carroz side is the strongest. L''Alpage de l''Airon sits by the Kédeuze gondola with a view across to Mont Blanc, Le Chalet des Molliets has a south facing terrace among the pistes on the Flaine road, and L''Igloo at the top of the Morillon chair is the priciest by Alpine Answers'' account. Halfway down the Cascades the Gîte du Lac de Gers opens when conditions allow, so it is worth booking.','{}','chapters.2.paras.2'),
('food','para',3,'Flaine is a different kind of place. Marcel Breuer''s concrete Forum and Forêt follow the contours of the bowl, with works by Picasso, Dubuffet and Vasarely set among the buildings, and the Forum is free of cars. Les Carroz is a Savoyard village with people living in it all year, Morillon keeps a church and bakery in the valley below its car free station, and Sixt is a quiet village of hamlets round its old abbey at the foot of the Cirque du Fer-à-Cheval, known for its frozen waterfalls and ice climbing.','{}','chapters.2.paras.3'),
('food','heading',1,'Tables and places worth the detour','{}','chapters.2.listTitle'),
('food','note',0,'Sources: <a href="https://guide.michelin.com/fr/fr/auvergne-rhone-alpes/chamonix-mont-blanc/restaurants">the Michelin Guide</a> (2026), <a href="https://www.alti-mag.com/alti-miam/quelles-sont-les-meilleures-tables-des-alpes-selon-le-gault-et-millau">Gault&Millau via Alti-Mag</a>, <a href="https://alpineanswers.co.uk/ski-resorts/france/resort-guide-flaine-samoens">Alpine Answers for Samoëns</a> and <a href="https://alpineanswers.co.uk/ski-resorts/france/resort-guide-flaine-les-carroz">for Les Carroz</a>, <a href="https://www.haute-savoie-tourisme.org/180925-le-chalet-des-molliets">Haute-Savoie tourism</a>, <a href="https://www.ernalow.co.uk/en-gb/france/morillon">Ernalow for Morillon</a>, and Wikipedia for <a href="https://en.wikipedia.org/wiki/Samo%C3%ABns">Samoëns</a>, <a href="https://en.wikipedia.org/wiki/Ja%C3%BFsinia">the Jaÿsinia</a> and <a href="https://en.wikipedia.org/wiki/Flaine">Flaine</a>. Sixt: <a href="https://guide-ski.fr/?p=10423">Guide Ski for Sixt</a>.','{}','chapters.2.note'),
('apres','kicker',0,'Après','{}','chapters.3.kicker'),
('apres','heading',0,'Après and evenings','{}','chapters.3.h2'),
('apres','para',0,'Flaine has the liveliest evenings. Le Pente à Jules draws a crowd to dance at its late afternoon DJ sets, Le White Pub has bands and sport on a big screen, and Brasserie Les Cimes has live music. In Flaine Forêt the Bam Pub serves food and games early and turns into a club later. Les Caves is the only nightclub, open from eleven at night until five, and Galaxy Bowling keeps its bar open until three.','{}','chapters.3.paras.0'),
('apres','para',1,'Samoëns is lively for a valley village, with about a dozen bars along its old streets by Ski Independence''s count. L''Après-Ski Chez Jeff has run a heated outdoor bar with mulled wine and DJs since {{f:F000676}}, the Evil Monkey is the pub for a big night, and Vin sur Vin pours wine. Alpine Answers still calls the evenings quiet, which suits a drink before dinner.',array['F000676'],'chapters.3.paras.1'),
('apres','para',2,'Les Carroz has The Marlow, the sunniest terrace on the square, La Pointe Noire for pool and occasional live music, busiest from about nine, and Carpe Diem and Club 74 for later. Morillon is calm, with Le Potet 2.0 for a beer and pizza without taking the skis off, and Sixt is quiet.','{}','chapters.3.paras.2'),
('apres','heading',1,'Where the evenings start','{}','chapters.3.listTitle'),
('apres','note',0,'Sources: <a href="https://www.igluski.com/blog/post/flaine-best-apres-nightlife">Iglu Ski</a>, <a href="https://ski-i.com/france/samoens/apres-ski">Ski Independence</a>, <a href="https://explore.samoens.com/en/bars/lapres-ski-chez-jeff">the Samoëns tourist office</a>, <a href="https://alpineanswers.co.uk/ski-resorts/france/resort-guide-flaine-samoens">Alpine Answers for Samoëns</a> and <a href="https://alpineanswers.co.uk/ski-resorts/france/resort-guide-flaine-les-carroz">for Les Carroz</a>, and <a href="https://www.ernalow.co.uk/en-gb/france/morillon">Ernalow for Morillon</a>.','{}','chapters.3.note'),
('fit','heading',0,'Who it suits','{}','fit.h2'),
('fit','line',0,'How the area suits different kinds of trip.','{}','fit.intro'),
('fit','line',1,'Exploring a large network','{}','fit.rows.0.who'),
('fit','line',2,'Good fit','{}','fit.rows.0.fit'),
('fit','line',3,'Five resorts on one lift network, with Flaine, Les Carroz and Morillon 1100 each one lift ride from Samoëns 1600.','{}','fit.rows.0.why'),
('fit','line',4,'Sixt is reached on skis only one way, down the Cascades.','{}','fit.rows.0.limit'),
('fit','line',5,'Intermediates who want variety','{}','fit.rows.1.who'),
('fit','line',6,'Good fit','{}','fit.rows.1.fit'),
('fit','line',7,'Green and blue reach every resort, and the long blues through the forest are the area''s strength.','{}','fit.rows.1.why'),
('fit','line',8,'The quick ways out of Flaine are often red.','{}','fit.rows.1.limit'),
('fit','line',9,'Groups of mixed ability','{}','fit.rows.2.who'),
('fit','line',10,'Good fit','{}','fit.rows.2.fit'),
('fit','line',11,'Samoëns 1600 and the Saix plateau put every level within a lift or two of each other.','{}','fit.rows.2.why'),
('fit','line',12,'The steep ground is all around Flaine.','{}','fit.rows.2.limit'),
('fit','line',13,'First timers','{}','fit.rows.3.who'),
('fit','line',14,'Good fit','{}','fit.rows.3.fit'),
('fit','line',15,'Big learning areas at Samoëns 1600, Morillon 1100 and Flaine, and cheap beginner passes in Flaine and Sixt.','{}','fit.rows.3.why'),
('fit','line',16,'The village slopes at Samoëns and Morillon are low and need a good winter.','{}','fit.rows.3.limit'),
('fit','line',17,'Families','{}','fit.rows.4.who'),
('fit','line',18,'Good fit','{}','fit.rows.4.fit'),
('fit','line',19,'Free day passes under {{f:F000688|n}}, Famille Plus in three villages and car free stations at Flaine and Morillon 1100.',array['F000688'],'fit.rows.4.why'),
('fit','line',20,'The valley villages start the day with a gondola ride.','{}','fit.rows.4.limit'),
('fit','line',21,'Snowboarders','{}','fit.rows.5.who'),
('fit','line',22,'Mixed','{}','fit.rows.5.fit'),
('fit','line',23,'Parks and a boardercross in Flaine and a big ungroomed bowl above it.','{}','fit.rows.5.why'),
('fit','line',24,'Drags are {{f:F000731}} of Flaine''s main lifts.',array['F000731'],'fit.rows.5.limit'),
('fit','line',25,'Experts','{}','fit.rows.6.who'),
('fit','line',26,'Mixed','{}','fit.rows.6.fit'),
('fit','line',27,'The Combe de Gers, Diamant Noir and the Lindars above Flaine.','{}','fit.rows.6.why'),
('fit','line',28,'Only {{f:F000529}} of the piste is rated difficult on skiresort.com.',array['F000529'],'fit.rows.6.limit'),
('fit','line',29,'Putting snow first','{}','fit.rows.7.who'),
('fit','line',30,'Good fit','{}','fit.rows.7.fit'),
('fit','line',31,'The most snowfall at 1,600 m of the four areas compared, and Flaine''s lifts start at {{f:F000727}}.',array['F000727'],'fit.rows.7.why'),
('fit','line',32,'The runs home to Samoëns and Morillon depend on a good winter.','{}','fit.rows.7.limit'),
('fit','line',33,'Travelling without a car','{}','fit.rows.8.who'),
('fit','line',34,'Mixed','{}','fit.rows.8.fit'),
('fit','line',35,'Buses from Cluses station to every resort, and free skibuses in the valley.','{}','fit.rows.8.why'),
('fit','line',36,'The Flaine buses run by reservation, and the change at Cluses adds time.','{}','fit.rows.8.limit'),
('fit','line',37,'Preferring a smaller area','{}','fit.rows.9.who'),
('fit','line',38,'Good fit','{}','fit.rows.9.fit'),
('fit','line',39,'The Villages pass covers {{f:F000656}} without Flaine for less.',array['F000656'],'fit.rows.9.why'),
('fit','line',40,'Flaine and the Cascades are then off the pass.','{}','fit.rows.9.limit'),
('fit','line',41,'Food lovers','{}','fit.rows.10.who'),
('fit','line',42,'Mixed','{}','fit.rows.10.fit'),
('fit','line',43,'A Bib Gourmand and good Savoyard cooking in Samoëns, and terraces above Les Carroz.','{}','fit.rows.10.why'),
('fit','line',44,'No Michelin stars in the area in the 2026 guide.','{}','fit.rows.10.limit'),
('fit','line',45,'Looking for après','{}','fit.rows.11.who'),
('fit','line',46,'Mixed','{}','fit.rows.11.fit'),
('fit','line',47,'Bars, DJs, bowling and a nightclub in Flaine, and a dozen bars in Samoëns.','{}','fit.rows.11.why'),
('fit','line',48,'Morillon and Sixt are quiet.','{}','fit.rows.11.limit'),
('fit','line',49,'Short trips from Geneva','{}','fit.rows.12.who'),
('fit','line',50,'Good fit','{}','fit.rows.12.fit'),
('fit','line',51,'Les Carroz is {{f:F000642}} from Geneva airport by road.',array['F000642'],'fit.rows.12.why'),
('fit','line',52,'Flaine is busy at weekends, as Alpine Answers notes.','{}','fit.rows.12.limit'),
('fit','heading',1,'The catches','{}','fit.catchesH3'),
('fit','line',53,'Height in the valleys is the main one. Samoëns and Morillon ski from close to {{f:F000742|n}} m, and three of the five lowest seasons in 76 years at 1,100 m came from 2022/23 to 2024/25 in the weather model. Sixt is joined only one way, by the Cascades, which often stays closed. Flaine is busy at weekends, with Geneva so close.',array['F000742'],'fit.catches'),
('compare','heading',0,'The other areas around Geneva','{}','compare.h2'),
('compare','para',0,'Set against its neighbours, the Grand Massif is the middle size: skiresort.com measures {{f:F000523}} of piste, against {{f:F000516}} in the Portes du Soleil, {{f:F000508}} across the two networks of Évasion Mont Blanc and {{f:F000709}} at La Clusaz. It tops out at {{f:F000526}}, a few metres below La Clusaz and well above the Portes du Soleil and Évasion Mont Blanc.',array['F000508','F000516','F000523','F000526','F000709'],'compare.paras.0'),
('compare','para',1,'Its six day pass, at {{f:F000533}}, costs {{diff:F000533,F000531}} more than the Portes du Soleil, {{diff:F000533,F000535}} more than Évasion Mont Blanc and {{diff:F000533,F000717}} more than La Clusaz. Its grid cell has the most snow of the four at 1,600 m in the weather model, and of the three larger areas it is the closest to Geneva.',array['F000531','F000533','F000535','F000717'],'compare.paras.1'),
('compare','caption',0,'Four ski areas within reach of Geneva','{}','compare.caption'),
